      "path": "src/handshake.ts",
      "content": "/** Pure handshake parser: turns a receiver AI's restatement into a verdict.
 * The contract (see taskbook.ts HANDSHAKE_TEXT) requires three blocks —
 * 【回读】 restatement, 【缺口】 gaps, and a STATUS line plus version stamp.
 * Anything short of that is an invalid handshake, never a silent pass. */

export type HandshakeStatus = 'ready' | 'need-input';

export interface Handshake {
  ok: boolean;
  status: HandshakeStatus | null;
  version: number | null;
  restatement: string;
  gaps: string[];
  issues: string[];
}

const STATUS_RE = /STATUS\s*[:：]\s*(READY|NEED[-_ ]?INPUT)/gi;
const VERSION_RE = /(?:version|版本)\s*[:：]?\s*v?(\d+)/gi;
const MARKERS = { restatement: '【回读】', gaps: '【缺口】' } as const;

/** 1. / 1、 / 1) / - 1. … numbered gap lines; bare "无" lines mean no gaps. */
const NUMBERED_RE = /^\s*(?:[-*]\s*)?(\d{1,3})\s*[.、)．]\s*(.+)$/;

/** `---` rules and the `**` left behind by a cut-off bold marker are not gaps. */
const CHROME_RE = /^[-*_~.＝=\s]+$/;

/** A section ends at the *other* contract marker or at a STATUS line. It must not
 * end at any 【…】 it sees: receivers bracket their own severity tags inside gap
 * items (`1. **【阻塞】**…`), and that used to truncate the list to nothing. */
function sectionAfter(text: string, marker: string): string {
  const start = text.indexOf(marker);
  if (start === -1) return '';
  const rest = text.slice(start + marker.length);
  const ends: number[] = [];
  for (const other of Object.values(MARKERS)) {
    if (other !== marker) ends.push(rest.indexOf(other));
  }
  ends.push(rest.search(/^\s*\*{0,2}STATUS\s*[:：]/im));
  const next = ends.filter((index) => index >= 0).sort((a, b) => a - b)[0] ?? -1;
  return (next === -1 ? rest : rest.slice(0, next)).trim();
}

/** 对方正文（复述/引用）里可能出现 STATUS 或 version 字样，协议结论永远在
 * 文本末尾——一律取最后一次匹配，避免把早前的引用文字当成结论。 */
function lastMatch(re: RegExp, text: string): RegExpExecArray | null {
  re.lastIndex = 0;
  let last: RegExpExecArray | null = null;
  for (let match = re.exec(text); match !== null; match = re.exec(text)) last = match;
  re.lastIndex = 0;
  return last;
}

export function parseHandshake(input: string): Handshake {
  const text = String(input ?? '');
  const issues: string[] = [];

  const statusMatch = lastMatch(STATUS_RE, text);
  const status = (statusMatch ? (statusMatch[1]!.toUpperCase().startsWith('READY') ? 'ready' : 'need-input') : null) as HandshakeStatus | null;
  if (!statusMatch) issues.push('缺少 STATUS 行（READY / NEED-INPUT）——没有明确放行，不能当握手通过');

  const versionMatch = lastMatch(VERSION_RE, text);
  const version = versionMatch ? Number.parseInt(versionMatch[1]!, 10) : null;
  if (version === null) issues.push('缺少 version 确认（接收方必须注明它读到的是哪一版）');

  const restatement = sectionAfter(text, MARKERS.restatement);
  if (!restatement) issues.push('缺少【回读】段——没有复述理解就不算确认');

  const rawGaps = sectionAfter(text, MARKERS.gaps);
  const gaps: string[] = [];
  if (!rawGaps) {
    issues.push('缺少【缺口】段');
  } else {
    for (const line of rawGaps.split(/\r?\n/)) {
      const clean = line.trim();
      if (!clean) continue;
      if (/^(无|none|没有)$/i.test(clean)) break;
      if (CHROME_RE.test(clean)) continue;
      const numbered = NUMBERED_RE.exec(clean);
      const body = (numbered ? numbered[2]! : clean.replace(/^[-*]\s*/, '')).replace(/\*\*/g, '').replace(/^[\s#]+|[\s]+$/g, '');
      if (!body || CHROME_RE.test(body)) continue;
      gaps.push(body);
    }
  }

  return { ok: status !== null && restatement !== '' && version !== null, status, version, restatement, gaps, issues };
}

/** A receiver that stamps READY while still listing questions has answered them on
 * the sender's behalf. That is not a green light — see the STATUS rule in HANDSHAKE_TEXT. */
export function needsSenderInput(hs: Handshake): boolean {
  return hs.gaps.length > 0 && (hs.status === 'need-input' || hs.status === 'ready');
}

export function isStaleVersion(hs: Handshake, current: number): boolean {
  return hs.version !== null && hs.version !== current;
}

export function renderAckReply(
  hs: Handshake,
  task: { id: string; version: number; title: string },
  target: string,
  gapQids: string[] = [],
): string {
  const gapLabel = (index: number): string => (gapQids[index] ? `G${index + 1} → ${gapQids[index]}` : `G${index + 1}`);
  if (!hs.ok) {
    return [
      `✗ ${target} 的回读不算有效握手（${task.id}@v${task.version}）：`,
      ...hs.issues.map((issue) => `- ${issue}`),
      '把下面这段补发给对方窗口，让它按格式重来回读：',
      `请按任务书 ${task.id}@v${task.version} 的握手指令回读：先【回读】复述目标/约束/验收标准，再【缺口】列出疑问，首行注明 version，末行 STATUS: READY 或 STATUS: NEED-INPUT。`,
    ].join('\n');
  }
  const stale = isStaleVersion(hs, task.version)
    ? [`⚠ 对方确认的是 v${hs.version}，最新版是 v${task.version}——回读按旧版处理，需要把最新版重新 relay 并让对方重新回读。`]
    : [];
  if (hs.status === 'ready') {
    if (stale.length) {
      // 旧版 READY 不是放行：不能与“可以放心开始”同时出现，只给重新 relay 指引。
      return [
        `⚠ ${target} 回读通过但基于旧版（${task.id}@v${task.version}，对方确认的是 v${hs.version}）——回读按旧版处理，先重新 relay，等它按 v${task.version} 回读后再开工。`,
        '后续所有交接引用该任务时都带上版本号：' + `${task.id}@v${task.version}。`,
      ].join('\n');
    }
    if (!needsSenderInput(hs)) {
      return [
        `✓ ${target} 回读通过（${task.id}@v${task.version}，STATUS: READY），可以放心让它开工。`,
        '后续所有交接引用该任务时都带上版本号：' + `${task.id}@v${task.version}。`,
      ].join('\n');
    }
  }
  const header = hs.status === 'ready'
    ? `△ ${target} 标了 READY 却列了 ${hs.gaps.length} 条缺口（${task.id}@v${task.version}）——缺口是它自己替你默认的，按 NEED-INPUT 处理：`
    : `△ ${target} 回读完成但有待补缺口（${task.id}@v${task.version}，STATUS: NEED-INPUT）：`;
  return [
    header,
    ...hs.gaps.map((gap, index) => `- ${gapLabel(index)}: ${gap}`),
    ...stale,
    hs.gaps.length
      ? `缺口已登记进任务书的开放缺口（${gapQids.join(' ') || '编号待定'}）。逐条 /answer ${task.id} <Q编号> <答案>，答完版本 +1，记得把新版重新 relay 给所有已交接的窗口。`
      : '对方标了 NEED-INPUT 但没列出具体缺口——直接问它缺什么。',
  ].join('\n');
}
